import React, { useState, useEffect } from 'react';

// Helper function to extract first name from full name
const getFirstName = (fullName) => {
  return fullName.split(' ')[0];
};

// Mock data generator - creates 6 active agents and 6 empty desks
const generateMockAgents = () => {
  const hebrewFirstNames = ['מאיר', 'אליה', 'יונתן', 'יעקב', 'שמעון', 'עדן'];
  const lastNames = ['כהן', 'לוי', 'ישראלי', 'דוד', 'בן דוד', 'אברהם', 'מוזס', 'שמעוני', 'פרץ', 'גולדברג'];
  const statuses = ['READY', 'NOT_READY'];

  const agents = [];

  // Generate 6 active agents (desks 1-6 on LEFT side)
  for (let i = 0; i < 6; i++) {
    const firstName = hebrewFirstNames[i % hebrewFirstNames.length];
    const lastName = lastNames[Math.floor(Math.random() * lastNames.length)];
    const status = statuses[Math.floor(Math.random() * statuses.length)];

    agents.push({
      id: i + 1,
      fullName: `${firstName} ${lastName}`,
      status: status,
      isEmpty: false,
      side: 'LEFT'
    });
  }

  // Generate 6 empty desks (desks 7-12 on RIGHT side)
  for (let i = 6; i < 12; i++) {
    agents.push({
      id: i + 1,
      fullName: 'עמדה ריקה',
      status: 'EMPTY',
      isEmpty: true,
      side: 'RIGHT'
    });
  }

  return agents;
};

// Simple components for metrics
const TotalDailyCalls = ({ totalDailyCalls }) => (
  <div className="bg-blue-500 text-white p-3 rounded">
    <div className="text-center">
      <div className="text-xl font-bold">{totalDailyCalls}</div>
      <div className="text-xs">Total Daily Calls</div>
    </div>
  </div>
);

const CallsWaiting = ({ callsWaiting }) => (
  <div className={`${callsWaiting > 0 ? 'bg-red-500' : 'bg-green-500'} text-white p-3 rounded`}>
    <div className="text-center">
      <div className="text-xl font-bold">{callsWaiting}</div>
      <div className="text-xs">Calls Waiting</div>
    </div>
  </div>
);

const CallCenterDashboard = () => {
  const [agents, setAgents] = useState([]);
  const [currentHour, setCurrentHour] = useState(new Date().getHours());

  // Initialize mock data
  useEffect(() => {
    setAgents(generateMockAgents());
  }, []);

  // Dynamic Day/Night Mode Effect
  useEffect(() => {
    const hour = new Date().getHours();
    setCurrentHour(hour);

    // Apply dark class for night mode, remove for day mode
    if (hour >= 18 || hour < 6) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const getStatusColor = (status, isEmpty) => {
    if (isEmpty) {
      return 'bg-gray-300 border-gray-400';
    }
    return status === 'READY' 
      ? 'bg-green-500 border-green-400' 
      : 'bg-red-500 border-red-400';
  };

  const getStatusIndicator = (status, isEmpty) => {
    if (isEmpty) {
      return (
        <div className="w-3 h-3 rounded-full bg-gray-400"></div>
      );
    }
    return (
      <div className={`w-3 h-3 rounded-full ${status === 'READY' ? 'bg-green-300' : 'bg-red-300'} animate-pulse`}></div>
    );
  };

  // Mock metrics data
  const totalDailyCalls = 452;
  const callsWaiting = 3;

  // Separate agents by side for proper rendering
  const leftAgents = agents.filter(agent => agent.side === 'LEFT');
  const rightAgents = agents.filter(agent => agent.side === 'RIGHT');

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold mb-2 text-blue-400">Call Center Dashboard</h1>
          <p className="text-gray-400">Real-time Agent Status Monitor</p>
        </div>

        {/* Room Layout Container */}
        <div className="bg-gray-800 rounded-lg p-8 shadow-2xl">
          <div 
            className="grid grid-cols-[400fr_230fr_400fr] relative"
            style={{ aspectRatio: '1030 / 380' }}
          >

            {/* Left Side - 6 Desks */}
            <div className="bg-gray-700 p-4 border-r border-gray-600">
              <div className="grid grid-cols-3 gap-3 h-full">
                {leftAgents.map((agent) => (
                  <div
                    key={agent.id}
                    className={`p-3 rounded border-2 ${getStatusColor(agent.status, agent.isEmpty)} 
                               transform transition-all duration-200 hover:scale-105
                               flex flex-col items-center justify-center text-center`}
                  >
                    <div className="flex flex-col items-center space-y-1">
                      <div className={`text-lg font-bold ${agent.isEmpty ? 'text-gray-500' : 'text-white'}`}>
                        {getFirstName(agent.fullName)}
                      </div>
                      {getStatusIndicator(agent.status, agent.isEmpty)}
                    </div>
                    <div className="text-xs text-gray-400 mt-1">
                      Desk {agent.id}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Central Aisle */}
            <div className="bg-gray-700 relative border-r border-gray-600">
              {/* Total Daily Calls Component */}
              <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20">
                <TotalDailyCalls totalDailyCalls={totalDailyCalls} />
              </div>

              {/* MAIN SCREEN */}
              <div className="absolute inset-0 flex items-center justify-center p-4">
                <div className="bg-gray-600 rounded p-4 text-center">
                  <div className="text-xs text-gray-300 mb-2">MAIN SCREEN</div>
                  <div className="text-2xl font-bold text-blue-400">
                    {agents.filter(a => !a.isEmpty && a.status === 'READY').length} / {agents.filter(a => !a.isEmpty).length}
                  </div>
                  <div className="text-xs text-gray-400">Ready</div>
                </div>
              </div>

              {/* Calls Waiting Component */}
              <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-20">
                <CallsWaiting callsWaiting={callsWaiting} />
              </div>
            </div>

            {/* Right Side - 6 Desks */}
            <div className="bg-gray-700 p-4">
              <div className="grid grid-cols-3 gap-3 h-full">
                {rightAgents.map((agent) => (
                  <div
                    key={agent.id}
                    className={`p-3 rounded border-2 ${getStatusColor(agent.status, agent.isEmpty)} 
                               transform transition-all duration-200 hover:scale-105
                               flex flex-col items-center justify-center text-center`}
                  >
                    <div className="flex flex-col items-center space-y-1">
                      <div className={`text-lg font-bold ${agent.isEmpty ? 'text-gray-500' : 'text-white'}`}>
                        {getFirstName(agent.fullName)}
                      </div>
                      {getStatusIndicator(agent.status, agent.isEmpty)}
                    </div>
                    <div className="text-xs text-gray-400 mt-1">
                      Desk {agent.id}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Legend */}
        <div className="mt-6 bg-gray-800 rounded-lg p-4">
          <div className="flex justify-between items-center">
            <div className="flex space-x-6">
              <div className="flex items-center space-x-2">
                <div className="w-4 h-4 bg-green-500 rounded"></div>
                <span className="text-sm text-gray-300">Ready</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-4 h-4 bg-red-500 rounded"></div>
                <span className="text-sm text-gray-300">Not Ready</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-4 h-4 bg-gray-300 rounded"></div>
                <span className="text-sm text-gray-300">Empty</span>
              </div>
            </div>

            <div className="text-sm text-gray-400">
              {currentHour >= 18 || currentHour < 6 ? '🌙 Night Mode' : '☀️ Day Mode'} ({currentHour}:00)
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CallCenterDashboard;
